header=['id','decision','sentences','what_it_does','basis','reason'];out=base/'part-tumbleweed.language.tsv';done=set()
if out.exists():done={x['id'] for x in csv.DictReader(out.open(),delimiter='\t')}
with out.open('a',newline='') as f:
 w=csv.writer(f,delimiter='\t',lineterminator='\n')
 if not out.stat().st_size:w.writerow(header);f.flush()
 for r in rows:
  if r['id'] in done:continue
  typ=r['kind'].split(':')[-1].replace('pip3','pip');n=r['name'].split(':',1)[1]
  if typ=='flatpak':continue
  if n in override and typ=='pip':url,quote,func=override[n]
  else:url,quote=docs[typ,n];func=functions[n]
  w.writerow([r['id'],'MUST','S2.2-9,S2.2-10',func,'doc:'+url,'Executable library or command code runs with the interpreter’s rights; installation method does not exempt it.']);f.flush()
